    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current number of open bins is low or the fit is truly terrible
        if open_bins_count > 0 {
            score += 45.0;
        }
        // Bias against opening new bins as the stream progresses to consolidate
        score += (step_index as f64 / total_items as f64) * 10.0;
    }

    // Bias toward using bins that are already partially filled (Best Fit logic)
    // Reward lower post_residual values more aggressively
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // If this is the only bin that can fit the item, prioritize it to avoid new bin overhead
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

