    // 4. Fitting constraints: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate too far from the average state.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.5;

