    let is_new_bin = bin_residual == bin_capacity;

    // Base: prioritize tighter fits, using a refined penalty for slivers to avoid fragmentation
    let mut score = post_residual as f64;
    if post_residual > 0 && post_residual < 52 {
        score += (52.0 - post_residual as f64).powf(1.82) * 28.5;
    }

    // Lookahead: Dynamic adjustment
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item, scaling with progression
            score -= 195.0 + (progress * 115.0);
            if post_residual == next_item_size {
                score -= 310.0; // Stronger perfect fit bonus for deterministic lookahead
            } else if post_residual < next_item_size + 12 {
                score -= 95.0; 
            }
        } else {
            // High penalty for blocking the next item, weighted by stream duration
            score += (next_item_size - post_residual) as f64 * (48.0 + (1.0 - progress) * 65.0);
        }
    }

    // Bin Management
    if is_new_bin {
        // Dynamic thresholding: increase cost for new bins based on current open bin density
        let new_bin_base_cost = 485.0 + (open_bins_count as f64 * 18.5) + (progress * 450.0);
        score += if fitting_bins_count == 0 { 0.0 } else { new_bin_base_cost };
    } else {
        // Density Balancing: Penalize deviation from the rolling mean
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * (3.5 - (progress * 1.1));

        // Tight-fit acceleration: Reward reaching high density (below 18)
        if post_residual < 18 {
            score -= (18.0 - post_residual as f64).powf(1.6) * 240.0;
        }
    }

    // Global Pressure: Non-linear penalty for opening too many concurrent bins
    if open_bins_count > 0 {
        score += (open_bins_count as f64).powf(2.65) * 9.2;
    }

    // Constraint Satisfaction: Force optimal bin selection
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 750.0; // Aggressive incentive to close single-fit gaps
        } else if fitting_bins_count > 1 {
            // Penalize loose fits non-linearly to favor compacting
            score += (post_residual as f64).powf(1.65) * 5.2;
        }
    }

    // Adaptive End-of-Stream Thresholding: 
    // Aggressively penalize wasted space late in the stream to force final compaction
    if progress > 0.65 && post_residual > 4 {
        score += (post_residual as f64).powf(2.15) * 2.4;
    }

    score
}

