    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are small but unusable (1..9 range).
    // These gaps are likely to remain wasted as item sizes are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global Bin Pressure: If fitting_bins_count is low, we are running out of options.
    // Discourage opening new bins unless the current options are truly terrible.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Heavily penalize opening a new bin if we have many existing bins with decent space.
        score += (open_bins_count as f64) * 15.0;
        score += mean_residual * 0.5;
    } else {
        // This is an existing bin. Reward using existing bins to keep open_bins_count low.
        score -= (open_bins_count as f64) * 2.0;

        // If this is the last chance to place the item in an existing bin, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 4. Distributional Balancing: Favor filling bins that are already closer to capacity.
    // This reduces the variance in residuals across open bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

