    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps.
    // If post_residual is small but not zero, it's often a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: Reward bins where the current post_residual 
    // is a tight fit for the next item, minimizing future fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect match for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap * 2.0);
        } else {
            // Cannot fit next item, penalize slightly based on how much space is wasted
            score += 10.0;
        }
    }

    // 3. Global Efficiency: If this is the only bin that can fit the current item,
    // we prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. New Bin Threshold: If considering a new bin, penalize it unless 
    // existing bins are highly fragmented.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean residual of existing bins is already very low
        // or if we are forced to (handled by the score relative to others).
        score += 40.0 + (mean_residual * 0.5);
    }

    // 5. Progression Scaling: As the stream nears the end, increase the 
    // aggressiveness of fitting into existing bins to avoid leftover items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

