    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base heuristic: Penalize slivers to force dense packing
    let mut score = post_residual as f64 * 1.55;
    if post_residual == 0 {
        score -= 320.0;
    } else if post_residual < 42 {
        score += (42.0 - post_residual as f64).powf(1.92) * 55.0;
    }

    // Lookahead: Refined weight for next_item_size anticipation
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let exact_match_bonus = if post_residual == next_item_size { 780.0 } else { 380.0 };
            score -= exact_match_bonus + (progress * 210.0);
        } else {
            score += (next_item_size - post_residual) as f64 * (145.0 + (1.0 - progress) * 160.0);
        }
    }

    // Bin Management: Dynamic cost to open, optimized for early vs late game
    if is_new_bin {
        let new_bin_base_cost = 840.0 + (open_bins_count as f64 * 52.0) + (progress * 620.0);
        score += if fitting_bins_count == 0 { 0.0 } else { new_bin_base_cost };
    } else {
        // Density Balancing: Use a tighter rolling mean window
        let target_res = mean_residual * 0.55;
        let deviation = (post_residual as f64 - target_res).abs();
        score += deviation * (5.2 - (progress * 1.8));

        // Tight-fit acceleration: Reward filling bins to near-capacity
        if post_residual < 12 {
            score -= (12.0 - post_residual as f64).powf(2.1) * 610.0;
        }
    }

    // Global Pressure: Non-linear penalty for opening too many concurrent bins
    if open_bins_count > 0 {
        score += (open_bins_count as f64).powf(2.75) * 22.0;
    }

    // Constraint Satisfaction: Prioritize unique fits with a penalty on capacity usage
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 1250.0;
        } else if fitting_bins_count > 1 {
            score += (post_residual as f64).powf(1.75) * 18.0;
        }
    }

    // Adaptive End-of-Stream: Aggressive compaction in the final 15%
    if progress > 0.85 {
        if post_residual == 0 {
            score -= 950.0;
        } else if post_residual <= 8 {
            score -= 520.0;
        } else {
            score += (post_residual as f64).powf(3.0) * 15.0;
        }
    }

    // Final entropy correction: discourage fragmented residual space across bins
    score += (bin_capacity - bin_residual) as f64 * (0.15 * progress);

    score
}

