    // 1. Penalize opening new bins unless necessary (fitting_bins_count == 0)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0; // Heavy penalty for opening a new bin prematurely
        } else {
            score -= 50.0;  // Incentive to open new bin when no other options exist
        }
    }

    // 2. Best-Fit logic: prioritize bins where the item fits tightly
    // We want to minimize post_residual, but avoid creating "dead space" that cannot be used by future items
    // If post_residual is too small (e.g., < 10), it might be unusable for most items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // Penalty for creating tiny, unusable slivers
    }

    // 3. Lookahead matching: check if the next item fits perfectly into the remaining space
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
            // Reward bins that create space for the next item
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalty if this choice makes it impossible to fit the next item in this bin
            score += 15.0;
        }
    }

    // 4. Distribution balancing: compare post_residual against the global mean
    // We want to keep residuals consistent to maximize future placement probability
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression scaling: as we near the end of the stream, prioritize space consolidation
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    score
}

