    // 1. Best-Fit Penalty: Penalize large remaining space (standard Best-Fit logic)
    // We favor smaller post_residuals. 

    // 2. Harmonic Class Logic:
    // We identify "dead zones" where the post_residual is too small to fit common items
    // but too large to be considered efficient. 
    // If post_residual is between 1 and 9, it is highly likely to be wasted space
    // as the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Integration:
    // If we have a next_item_size, we penalize bins that cannot accommodate it
    // if the current bin is the only one that could potentially hold it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that leaves no room for the next item
            score += 25.0;
        } else {
            // Reward bins that create a perfect fit or near-perfect fit for the next item
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 15.0;
            }
        }
    }

    // 4. Density Balancing:
    // Avoid opening new bins unless necessary. If this is an empty bin (bin_residual == bin_capacity),
    // heavily penalize it unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0; // High penalty for opening a new bin prematurely
        }
    }

    // 5. Global State Awareness:
    // If the mean_residual of current bins is high, we are being inefficient.
    // We penalize current bin selections that increase this mean further.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 6. Progression Scaling:
    // As we near the end of the stream, prioritize closing bins (lower score for tighter fits).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core adjustment: penalize fragmentation more heavily in the early phase
    let mut score = post_residual as f64 * 1.65;

    // Refined sliver penalty with non-linear decay
    if post_residual == 0 {
        score -= 340.0;
    } else if post_residual < 42 {
        score += (42.0 - post_residual as f64).powf(2.1) * 55.0;
    }

    // Lookahead: Refined weight for next_item_size anticipation
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let exact_match_bonus = if post_residual == next_item_size { 780.0 } else { 380.0 };
            score -= exact_match_bonus + (progress * 210.0);
        } else {
            // Increased pressure to keep bins open for potential next_item_size matches
            score += (next_item_size - post_residual) as f64 * (145.0 + (1.0 - progress) * 160.0);
        }
    }

    // Bin Management: Dynamic threshold for new bin creation
    if is_new_bin {
        // Adjusted cost based on density pressure
        let new_bin_base_cost = 880.0 + (open_bins_count as f64 * 58.0) + (progress * 720.0);
        score += if fitting_bins_count == 0 { 0.0 } else { new_bin_base_cost };
    } else {
        // Density Balancing: Use a tighter rolling mean window
        let target_res = mean_residual * 0.55;
        let deviation = (post_residual as f64 - target_res).abs();
        score += deviation * (5.8 - (progress * 1.5));

        // Tight-fit acceleration: Reward filling bins to near-capacity
        if post_residual < 12 {
            score -= (12.0 - post_residual as f64).powf(2.1) * 680.0;
        }
    }

    // Global Pressure: Non-linear penalty for opening too many concurrent bins
    if open_bins_count > 0 {
        score += (open_bins_count as f64).powf(2.8) * 22.0;
    }

    // Constraint Satisfaction: Prioritize unique fits
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 1350.0;
        } else if fitting_bins_count > 1 {
            score += (post_residual as f64).powf(1.8) * 18.0;
        }
    }

    // Adaptive End-of-Stream: Aggressive compaction in the final 15%
