pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: Penalize slivers more aggressively to force dense packings
    let mut score = post_residual as f64 * 1.62;
    if post_residual == 0 {
        score -= 325.0;
    } else if post_residual < 45 {
        score += (45.0 - post_residual as f64).powf(2.0) * 55.0;
    }

    // Lookahead: Refined weight for next_item_size anticipation
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let exact_match_bonus = if post_residual == next_item_size { 720.0 } else { 360.0 };
            score -= exact_match_bonus + (progress * 200.0);
        } else {
            // Increased penalty for blocking the next item
            score += (next_item_size - post_residual) as f64 * (145.0 + (1.0 - progress) * 160.0);
        }
    }

    // Bin Management: Dynamic cost to open, optimized for early vs late game
    if is_new_bin {
        let new_bin_base_cost = 810.0 + (open_bins_count as f64 * 60.0) + (progress * 680.0);
        score += if fitting_bins_count == 0 { 0.0 } else { new_bin_base_cost };
    } else {
        // Density Balancing: Use a tighter rolling mean window
        let target_res = mean_residual * 0.58;
        let deviation = (post_residual as f64 - target_res).abs();
        score += deviation * (5.5 - (progress * 1.8));

        // Tight-fit acceleration: Reward filling bins to near-capacity
        if post_residual < 14 {
            score -= (14.0 - post_residual as f64).powf(2.15) * 620.0;
        }
    }

    // Global Pressure: Non-linear penalty for opening too many concurrent bins
    if open_bins_count > 0 {
        score += (open_bins_count as f64).powf(2.85) * 25.0;
    }

    // Constraint Satisfaction: Prioritize unique fits
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 1350.0;
        } else if fitting_bins_count > 1 {
            score += (post_residual as f64).powf(1.8) * 22.0;
        }
    }

    // Adaptive End-of-Stream: Aggressive compaction in the final 12%
    if progress > 0.88 {
        if post_residual == 0 {
            score -= 1100.0;
        } else if post_residual <= 10 {
            score -= 600.0;
        } else {
            score += (post_residual as f64).powf(3.2) * 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit typical items, 
    // it is highly undesirable (fragmentation). We penalize post_residuals < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // prioritize this bin heavily to avoid leaving a gap.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), add a threshold cost.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Density Balancing: Favor bins that bring the bin residual closer to the global mean.
    // This helps keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last Chance Heuristic: If this is the only bin that fits the current item, 
    // we should prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

